create or replace function hnk_private.validate_day065_completion_v2(p_evidence jsonb,p_expected_source_sha text)
returns void language plpgsql set search_path=''
as $function$
declare a jsonb;c jsonb;p jsonb;m jsonb;s jsonb;k text;r text;care text;
begin
 if jsonb_typeof(p_evidence) is distinct from 'object' then raise exception 'day065_v2_evidence_object_required';end if;
 if exists(select 1 from jsonb_object_keys(p_evidence) x where x not in ('protocol_version','source_sha','session_id','mode','active','control','comparison','middle','private_vault_entry_ref','private_vault_e2ee_confirmed','practice_record_no_third_party_data_confirmed','voluntary_completion_confirmed','final_safety_clear_confirmed','safety_stop_occurred','safety_stop_reason')) then raise exception 'day065_v2_unknown_top_field';end if;
 if p_evidence->>'protocol_version' is distinct from 'HNK-CHOKMAH-D065-V2' then raise exception 'day065_v2_protocol_invalid';end if;
 if p_evidence->>'source_sha' is distinct from p_expected_source_sha or p_expected_source_sha is distinct from '8d8cd2a39fb05be283b8326fa258ed547b40f442' then raise exception 'day065_v2_source_sha_invalid';end if;
 if nullif(btrim(p_evidence->>'session_id'),'') is null then raise exception 'day065_v2_session_required';end if;
 if coalesce(p_evidence->>'mode','first_completion') not in ('first_completion','revisit') then raise exception 'day065_v2_mode_invalid';end if;
 if p_evidence->'practice_record_no_third_party_data_confirmed' is distinct from 'true'::jsonb or p_evidence->'voluntary_completion_confirmed' is distinct from 'true'::jsonb or p_evidence->'final_safety_clear_confirmed' is distinct from 'true'::jsonb then raise exception 'day065_v2_completion_boundary_missing';end if;
 if p_evidence->'safety_stop_occurred' is distinct from 'false'::jsonb or p_evidence->>'safety_stop_reason' is distinct from 'NONE' then raise exception 'day065_v2_unresolved_safety_stop';end if;
 r:=p_evidence->>'private_vault_entry_ref';if r is null then if p_evidence ? 'private_vault_e2ee_confirmed' then raise exception 'day065_v2_vault_flag_without_ref';end if;else if r!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'day065_v2_vault_ref_invalid';end if;if p_evidence->'private_vault_e2ee_confirmed' is distinct from 'true'::jsonb then raise exception 'day065_v2_vault_e2ee_required';end if;end if;
 a:=p_evidence->'active';if jsonb_typeof(a) is distinct from 'object' then raise exception 'day065_v2_active_required';end if;
 if exists(select 1 from jsonb_object_keys(a) x where x not in ('duration_seconds','photo_used_locally','consent_applicable','consent_confirmed_if_applicable','practitioner_effect_present','scores','active_completed_confirmed','simple_good_intention_confirmed','no_diagnosis_confirmed','no_result_promise_confirmed','photo_not_uploaded_confirmed','third_party_identity_not_stored_confirmed','third_party_symptoms_not_collected_confirmed','professional_care_not_replaced_confirmed','no_unsolicited_medical_advice_confirmed','concrete_care_considered_confirmed','remote_effect_not_claimed_confirmed','return_from_visualization_confirmed')) then raise exception 'day065_v2_active_unknown_field';end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(a->'duration_seconds'),false) or (a->>'duration_seconds')::integer<1 then raise exception 'day065_v2_active_duration_incomplete';end if;
 foreach k in array array['photo_used_locally','consent_applicable','consent_confirmed_if_applicable','practitioner_effect_present'] loop if jsonb_typeof(a->k) is distinct from 'boolean' then raise exception 'day065_v2_active_boolean_invalid:%',k;end if;end loop;
 if a->'consent_applicable'='true'::jsonb and a->'consent_confirmed_if_applicable' is distinct from 'true'::jsonb then raise exception 'day065_v2_consent_required';end if;
 foreach k in array array['active_completed_confirmed','simple_good_intention_confirmed','no_diagnosis_confirmed','no_result_promise_confirmed','photo_not_uploaded_confirmed','third_party_identity_not_stored_confirmed','third_party_symptoms_not_collected_confirmed','professional_care_not_replaced_confirmed','no_unsolicited_medical_advice_confirmed','concrete_care_considered_confirmed','remote_effect_not_claimed_confirmed','return_from_visualization_confirmed'] loop if a->k is distinct from 'true'::jsonb then raise exception 'day065_v2_active_boundary_required:%',k;end if;end loop;
 s:=a->'scores';if jsonb_typeof(s) is distinct from 'object' or exists(select 1 from jsonb_object_keys(s) x where x not in ('calm','compassion','urgency','willingness_to_help')) then raise exception 'day065_v2_active_scores_invalid';end if;foreach k in array array['calm','compassion','urgency','willingness_to_help'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(s->k),false) or (s->>k)::integer>10 then raise exception 'day065_v2_active_score_invalid:%',k;end if;end loop;
 c:=p_evidence->'control';if jsonb_typeof(c) is distinct from 'object' then raise exception 'day065_v2_control_required';end if;
 if exists(select 1 from jsonb_object_keys(c) x where x not in ('duration_seconds','practitioner_effect_present','scores','control_completed_confirmed','no_photo_confirmed','no_white_light_visualization_confirmed','own_experience_only_confirmed','energy_validation_not_sought_confirmed','ordinary_respectful_contact_only_confirmed')) then raise exception 'day065_v2_control_unknown_field';end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->'duration_seconds'),false) or (c->>'duration_seconds')::integer<1 then raise exception 'day065_v2_control_duration_incomplete';end if;if jsonb_typeof(c->'practitioner_effect_present') is distinct from 'boolean' then raise exception 'day065_v2_control_effect_invalid';end if;
 foreach k in array array['control_completed_confirmed','no_photo_confirmed','no_white_light_visualization_confirmed','own_experience_only_confirmed','energy_validation_not_sought_confirmed','ordinary_respectful_contact_only_confirmed'] loop if c->k is distinct from 'true'::jsonb then raise exception 'day065_v2_control_boundary_required:%',k;end if;end loop;
 s:=c->'scores';if jsonb_typeof(s) is distinct from 'object' or exists(select 1 from jsonb_object_keys(s) x where x not in ('calm','compassion','urgency','willingness_to_help')) then raise exception 'day065_v2_control_scores_invalid';end if;foreach k in array array['calm','compassion','urgency','willingness_to_help'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(s->k),false) or (s->>k)::integer>10 then raise exception 'day065_v2_control_score_invalid:%',k;end if;end loop;
 p:=p_evidence->'comparison';if jsonb_typeof(p) is distinct from 'object' then raise exception 'day065_v2_comparison_required';end if;
 if exists(select 1 from jsonb_object_keys(p) x where x not in ('completed_confirmed','after_both_conditions_confirmed','own_experience_only_confirmed','no_cure_score_confirmed','remote_effect_unmeasured_confirmed','remote_effect_not_claimed_confirmed','third_party_improvement_not_used_as_proof_confirmed','privacy_respected_confirmed','professional_care_prioritized_confirmed')) then raise exception 'day065_v2_comparison_unknown_field';end if;foreach k in array array['completed_confirmed','after_both_conditions_confirmed','own_experience_only_confirmed','no_cure_score_confirmed','remote_effect_unmeasured_confirmed','remote_effect_not_claimed_confirmed','third_party_improvement_not_used_as_proof_confirmed','privacy_respected_confirmed','professional_care_prioritized_confirmed'] loop if p->k is distinct from 'true'::jsonb then raise exception 'day065_v2_comparison_boundary_required:%',k;end if;end loop;
 m:=p_evidence->'middle';if jsonb_typeof(m) is distinct from 'object' then raise exception 'day065_v2_middle_required';end if;
 if exists(select 1 from jsonb_object_keys(m) x where x not in ('psalm_98_4_confirmed','yod_zayin_lamed_confirmed','person_surrendered_to_god_confirmed','care_category','care_respects_consent_and_limits_confirmed','prayer_closure_if_no_action_confirmed','visualization_not_diagnosis_confirmed','visualization_not_physical_proof_confirmed','thanks_to_god_confirmed','movement_and_return_confirmed')) then raise exception 'day065_v2_middle_unknown_field';end if;foreach k in array array['psalm_98_4_confirmed','yod_zayin_lamed_confirmed','person_surrendered_to_god_confirmed','care_respects_consent_and_limits_confirmed','prayer_closure_if_no_action_confirmed','visualization_not_diagnosis_confirmed','visualization_not_physical_proof_confirmed','thanks_to_god_confirmed','movement_and_return_confirmed'] loop if m->k is distinct from 'true'::jsonb then raise exception 'day065_v2_middle_boundary_required:%',k;end if;end loop;
 care:=m->>'care_category';if care not in ('MESSAGE','HELP','PRESENCE','PRAYER','NONE') then raise exception 'day065_v2_care_category_invalid';end if;
 perform hnk_private.validate_day065_scalar_evidence_v1(jsonb_build_object('protocol_completed',true,'return_confirmed',m->'movement_and_return_confirmed','active_completed',a->'active_completed_confirmed','control_completed',c->'control_completed_confirmed','comparison_completed',p->'completed_confirmed','photo_not_uploaded',a->'photo_not_uploaded_confirmed','third_party_identity_not_stored',a->'third_party_identity_not_stored_confirmed','third_party_symptoms_not_collected',a->'third_party_symptoms_not_collected_confirmed','cure_not_claimed',p->'no_cure_score_confirmed','remote_effect_not_claimed',p->'remote_effect_not_claimed_confirmed','professional_care_not_replaced',a->'professional_care_not_replaced_confirmed','concrete_care_considered',a->'concrete_care_considered_confirmed','safety_clear',p_evidence->'final_safety_clear_confirmed','photo_used_locally',a->'photo_used_locally','consent_applicable',a->'consent_applicable','consent_confirmed_if_applicable',a->'consent_confirmed_if_applicable','active_effect_present',a->'practitioner_effect_present','control_effect_present',c->'practitioner_effect_present','active_seconds',a->'duration_seconds','control_seconds',c->'duration_seconds'));
end$function$;

create or replace function hnk_private.enforce_iezalel_062_066_scalar_evidence()
returns trigger language plpgsql security definer set search_path=''
as $function$
declare v_existing boolean;v_source_sha text;v_status text;
begin
 if new.day not in (62,63,64,65,66) or new.state not in ('evidence_pending','complete') then return new;end if;
 select exists(select 1 from public.day_completions where user_id=new.user_id and day=new.day) into v_existing;if v_existing then return new;end if;
 select source_sha,status into v_source_sha,v_status from public.codex_days where day=new.day;if v_status is distinct from 'canon' then raise exception 'iezalel_canonical_day_not_available';end if;
 if new.day=62 then if v_source_sha is distinct from '56a8aaafbd2d602324ecfb9c06da39563fefaaf6' then raise exception 'day062_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D062-V2' then perform hnk_private.validate_day062_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day062_scalar_evidence_v1(new.evidence);end if;
 elsif new.day=63 then if v_source_sha is distinct from 'b9c9872ddf618aff3f515f601b3abfd611dace46' then raise exception 'day063_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D063-V2' then perform hnk_private.validate_day063_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day063_scalar_evidence_v1(new.evidence);end if;
 elsif new.day=64 then if v_source_sha is distinct from 'fb05d22be494099a5a1d3e1e0f5480ecc6c072cb' then raise exception 'day064_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D064-V2' then perform hnk_private.validate_day064_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day064_scalar_evidence_v1(new.evidence);end if;
 elsif new.day=65 then if v_source_sha is distinct from '8d8cd2a39fb05be283b8326fa258ed547b40f442' then raise exception 'day065_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D065-V2' then perform hnk_private.validate_day065_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day065_scalar_evidence_v1(new.evidence);end if;
 else if v_source_sha is distinct from 'a6d48785ee355f734cadda61b0bb3810b125bf5e' then raise exception 'day066_canonical_source_sha_mismatch';end if;perform hnk_private.validate_day066_scalar_evidence_v1(new.evidence);end if;return new;
end$function$;

do $patch$
declare d text;
begin select pg_get_functiondef('hnk_private.validate_completion_contract_v2(text,jsonb,text)'::regprocedure) into d;if position('when ''day065_v2''' in d)=0 then d:=replace(d,'  when ''day064_v2'' then perform hnk_private.validate_day064_completion_v2(p_evidence,p_expected_source_sha);','  when ''day064_v2'' then perform hnk_private.validate_day064_completion_v2(p_evidence,p_expected_source_sha);'||E'\n'||'  when ''day065_v2'' then perform hnk_private.validate_day065_completion_v2(p_evidence,p_expected_source_sha);');execute d;end if;end$patch$;

insert into hnk_private.completion_contract_registry(completion_contract_id,quest_definition_id,day,canonical_source_sha,contract_version,validator_key,status)
values('HNK-CHOKMAH-D065-COMP-V2','HNK-CHOKMAH-D065-V2',65,'8d8cd2a39fb05be283b8326fa258ed547b40f442','2.0.0','day065_v2','draft')
on conflict(completion_contract_id) do update set quest_definition_id=excluded.quest_definition_id,day=excluded.day,canonical_source_sha=excluded.canonical_source_sha,contract_version=excluded.contract_version,validator_key=excluded.validator_key,status='draft',updated_at=now();
